14	func TestParsePathTarget(t *testing.T) {
15		const (
16			errPort = "port must be a number between 1 and 65535"
17			errV6   = "the path trace supports IPv4 targets only"
18		)
19		tests := []struct {
20			name    string
21			in      string
22			want    pathTarget
23			wantErr string
24		}{
25			{"ipv4", "1.1.1.1", pathTarget{Host: "1.1.1.1"}, ""},
26			{"host with port", "example.com:443", pathTarget{Host: "example.com", Port: 443}, ""},
27			{"trimmed", " host ", pathTarget{Host: "host"}, ""},
28			{"ipv4 with port", "10.0.0.1:65535", pathTarget{Host: "10.0.0.1", Port: 65535}, ""},
29			{"empty", "", pathTarget{}, "target is required"},
30			{"blank", "   ", pathTarget{}, "target is required"},
31			{"space inside", "a b", pathTarget{}, "target must be a hostname or IP address"},
32			{"port zero", "host:0", pathTarget{}, errPort},
33			{"port too large", "host:70000", pathTarget{}, errPort},
34			{"port not a number", "host:x", pathTarget{}, errPort},
35			{"ipv6 loopback", "::1", pathTarget{}, errV6},
36			{"ipv6 bracketed with port", "[::1]:443", pathTarget{}, errV6},
37			{"ipv6 global", "2001:db8::1", pathTarget{}, errV6},
38		}
39		for _, tt := range tests {
40			t.Run(tt.name, func(t *testing.T) {
41				got, err := parsePathTarget(tt.in)
42				if tt.wantErr != "" {
43					if err == nil || err.Error() != tt.wantErr {
44						t.Fatalf("parsePathTarget(%q) error = %v, want %q", tt.in, err, tt.wantErr)
45					}
46					return
47				}
48				if err != nil {
49					t.Fatalf("parsePathTarget(%q) unexpected error: %v", tt.in, err)
50				}
51				if got != tt.want {
52					t.Errorf("parsePathTarget(%q) = %+v, want %+v", tt.in, got, tt.want)
53				}
54			})
55		}
56	}
57	
58	func TestPathTargetString(t *testing.T) {
59		tests := []struct {
60			tg   pathTarget
61			want string
62		}{
63			{pathTarget{Host: "1.1.1.1"}, "1.1.1.1"},
64			{pathTarget{Host: "example.com", Port: 443}, "example.com:443"},
65		}
66		for _, tt := range tests {
67			if got := tt.tg.String(); got != tt.want {
68				t.Errorf("%+v.String() = %q, want %q", tt.tg, got, tt.want)
69			}
70		}
71	}
72	
73	func TestVisiblePathHops(t *testing.T) {
74		h := func(ttl int, k nettrace.HopKind) nettrace.Hop { return nettrace.Hop{TTL: ttl, Kind: k} }
75		ttls := func(hops []nettrace.Hop) []int {
76			out := []int{}
77			for _, x := range hops {
78				out = append(out, x.TTL)
79			}
80			return out
81		}
82		tests := []struct {
83			name string
84			in   []nettrace.Hop
85			want []int
86		}{
87			{"sorted by TTL", []nettrace.Hop{h(3, nettrace.HopRouter), h(1, nettrace.HopRouter)}, []int{1, 3}},
88			{"cut after first target", []nettrace.Hop{h(1, nettrace.HopRouter), h(2, nettrace.HopTarget), h(3, nettrace.HopTarget)}, []int{1, 2}},
89			{"cut after first target, unsorted", []nettrace.Hop{h(3, nettrace.HopTarget), h(2, nettrace.HopTarget), h(1, nettrace.HopRouter)}, []int{1, 2}},
90			{"cut after unreachable", []nettrace.Hop{h(1, nettrace.HopRouter), h(2, nettrace.HopUnreachable), h(3, nettrace.HopRouter)}, []int{1, 2}},
91			{"unresolved dropped", []nettrace.Hop{h(1, nettrace.HopUnresolved), h(2, nettrace.HopRouter)}, []int{2}},
92			{"silent and error kept", []nettrace.Hop{h(1, nettrace.HopSilent), h(2, nettrace.HopError), h(3, nettrace.HopRouter)}, []int{1, 2, 3}},
93			{"empty", nil, []int{}},
94		}
95		for _, tt := range tests {
96			t.Run(tt.name, func(t *testing.T) {
97				orig := append([]nettrace.Hop(nil), tt.in...)
98				got := visiblePathHops(tt.in)
99				if !reflect.DeepEqual(ttls(got), tt.want) {
100					t.Errorf("TTLs = %v, want %v", ttls(got), tt.want)
101				}
102				if !reflect.DeepEqual(tt.in, orig) {
103					t.Errorf("input was modified: %v, want %v", tt.in, orig)
104				}
105			})
106		}
107	}
